import heapq


def _resolver(data, order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    choices = [[None] + list(rows[name]) for name in names]
    best_key = None
    best = None

    for values in product(*choices):
        selected = {name: version for name, version in zip(names, values)
                    if version is not None}
        if any(name not in selected or not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue
        if any(version in blocked.get(name, []) or
               (name in pins and pins[name] != version)
               for name, version in selected.items()):
            continue

        graph = {}
        valid = True
        for name, version in selected.items():
            deps = [dep for dep in rows[name][version].get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            graph[name] = [dep["name"] for dep in deps]
            for dep in deps:
                other = selected.get(dep["name"])
                if other is None or not dep["min"] <= other <= dep["max"]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        if reachable != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in selected):
            continue

        key = tuple(selected.get(name, -1) for name in names)
        if best_key is None or (key > best_key if preference == "maximum" else key < best_key):
            best_key, best = key, selected
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _c01(d): return _resolver(d, "descending", "maximum")
def _c02(d): return _resolver(d, "descending", "minimum")
def _c03(d): return _resolver(d, "ascending", "maximum")
def _c04(d): return _resolver(d, "ascending", "minimum")
def _c05(d): return _resolver(d, "descending", "maximum")


def _c06(data):
    mode = data["rounding"]
    def rounded(n, d):
        return (n + d // 2) // d if mode == "half_up" else n // d

    winners = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _c07(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = [job["id"] for job in chosen]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        intervals = sorted((job["start"], job["end"]) for job in chosen)
        active = []
        compatible = True
        for start, end in intervals:
            while active and active[0] <= start:
                heapq.heappop(active)
            heapq.heappush(active, end)
            if len(active) > 2:
                compatible = False
                break
        if not compatible:
            continue
        ids.sort()
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _c08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source, start = data["source"], data["start"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    dist = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and time <= data["deadline"]:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit_for.get(nxt, 0)
                next_state = (nxt, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


